preConditionHook:
// Long side. Walk back from bar 1 while the bars close DOWN; kkLong lands on
// the OLDEST bar of that run -- the bar that started the pullback. The scan is
// capped at maxScanBars because the corpus needs a fixed Max Bars Back, and the
// deepest reference is high[maxScanBars + 1]. kkLong = 0 means bar 1 is not a
// down-close bar, so no pullback is under way and the filter passes.
//
// The veto is that starting bar being a strong bear reversal bar that also made
// a HIGHER high than the bar before it: body at least bodyFraction of its range
// and BOTH tails no more than tailFraction of it -- the same shape StrongTrendBar
// tests, but evaluated at a bar offset the rule has to find, which is why it is
// written out here rather than composed from that rule.
//
// Stated in the PASSING sense (okLong), so the condition needs no negation and a
// placement wanting Brooks's veto negates the placement. Comparisons are
// multiplied, never ratios: EL raises a runtime divide-by-zero on a doji whose
// high = low. Every variable offset is on a DATA series, never a history
// reference on a function call -- the case FailedBreakoutReversal open-codes for.
//
// Every local persists across bars, so all seven are reset at the top.
kkLong = 0;
scanLong = true;
kkShort = 0;
scanShort = true;
for (int i = 1; i <= (int)maxScanBars; ++i) {
    if (scanLong && el_lt(close[i], open[i])) {
        kkLong = i;
    } else {
        scanLong = false;
    }
    if (scanShort && el_gt(close[i], open[i])) {
        kkShort = i;
    } else {
        scanShort = false;
    }
}
okLong = true;
if (kkLong > 0) {
    rng = high[kkLong] - low[kkLong];
    if (el_ge(open[kkLong] - close[kkLong], bodyFraction * rng)
        && el_le(high[kkLong] - open[kkLong], tailFraction * rng)
        && el_le(close[kkLong] - low[kkLong], tailFraction * rng)
        && el_gt(high[kkLong], high[kkLong + 1])) {
        okLong = false;
    }
}
okShort = true;
if (kkShort > 0) {
    rng = high[kkShort] - low[kkShort];
    if (el_ge(close[kkShort] - open[kkShort], bodyFraction * rng)
        && el_le(high[kkShort] - close[kkShort], tailFraction * rng)
        && el_le(open[kkShort] - low[kkShort], tailFraction * rng)
        && el_lt(low[kkShort], low[kkShort + 1])) {
        okShort = false;
    }
}
